use entropylab_hex_core::el_hex_run;
fn run(h:&[u8])->(i32,[u8;216],[u8;9],[u8;43]) { let(mut m,mut f,mut a)=([0xa5;216],[0xa5;9],[0xa5;43]);let r=unsafe{el_hex_run(h.as_ptr(),h.len(),m.as_mut_ptr(),216,f.as_mut_ptr(),9,a.as_mut_ptr(),43)};(r,m,f,a)}
fn text(b:&[u8])->&str{std::str::from_utf8(b.split(|b|*b==0).next().unwrap()).unwrap()}
#[test] fn all_24_published_bip39_vectors(){let mut count=0;for line in include_str!("../vectors/bip39-english.tsv").lines(){let v:Vec<_>=line.split('\t').collect();let(r,m,_,_)=run(v[0].as_bytes());assert_eq!(r,0);assert_eq!(text(&m),v[1]);let mnemonic=bip39::Mnemonic::parse_in_normalized(bip39::Language::English,v[1]).unwrap();let trezor:String=mnemonic.to_seed_normalized("TREZOR").iter().map(|b|format!("{b:02x}")).collect();assert_eq!(trezor,v[2]);count+=1;}assert_eq!(count,24);}
#[test] fn strict_hex_and_lengths(){for n in 0..=130{let h=vec![b'0';n];let(r,m,f,a)=run(&h);if [32,40,48,56,64].contains(&n){assert_eq!(r,0);assert_eq!(text(&m).split_whitespace().count(),n*3/8);}else{assert_eq!(r,-1);assert_eq!(m,[0xa5;216]);assert_eq!(f,[0xa5;9]);assert_eq!(a,[0xa5;43]);}}for b in [b' ',b'\t',b'\n',b'g',0,0xff]{let mut h=[b'0';32];h[15]=b;let(r,m,f,a)=run(&h);assert_eq!(r,-4);assert_eq!(m,[0xa5;216]);assert_eq!(f,[0xa5;9]);assert_eq!(a,[0xa5;43]);}assert_eq!(run(b"abcdefABCDEFabcdefABCDEFabcdefAB"),run(b"ABCDEFabcdefABCDEFabcdefABCDEFab"));}
#[test] fn pointer_caps_and_sentinels(){unsafe{let h=[b'0';32];let(mut m,mut f,mut a)=([0xa5;218],[0xa5;11],[0xa5;45]);let mp=m.as_mut_ptr().add(1);let fp=f.as_mut_ptr().add(1);let ap=a.as_mut_ptr().add(1);for cap in 0..94{let expected=if cap==0{-1}else{-2};assert_eq!(el_hex_run(h.as_ptr(),32,mp,cap,fp,9,ap,43),expected);assert_eq!(m,[0xa5;218]);assert_eq!(f,[0xa5;11]);assert_eq!(a,[0xa5;45]);}for (hc,mc,fc,ac) in [(usize::MAX,216,9,43),(32,217,9,43),(32,216,10,43),(32,216,9,44),(32,216,0,43),(32,216,9,0)]{assert_eq!(el_hex_run(h.as_ptr(),hc,mp,mc,fp,fc,ap,ac),-1);}assert_eq!(el_hex_run(core::ptr::null(),32,mp,216,fp,9,ap,43),-1);assert_eq!(el_hex_run(h.as_ptr(),32,core::ptr::null_mut(),216,fp,9,ap,43),-1);assert_eq!(el_hex_run(h.as_ptr(),32,mp,216,mp,9,ap,43),-1);assert_eq!(el_hex_run(mp,32,mp,216,fp,9,ap,43),-1);assert_eq!(el_hex_run(usize::MAX as *const u8,32,mp,216,fp,9,ap,43),-1);assert_eq!(el_hex_run(h.as_ptr(),32,mp,216,fp,8,ap,43),-2);assert_eq!(el_hex_run(h.as_ptr(),32,mp,216,fp,9,ap,42),-2);assert_eq!(m,[0xa5;218]);assert_eq!(f,[0xa5;11]);assert_eq!(a,[0xa5;45]);assert_eq!(el_hex_run(h.as_ptr(),32,mp,94,fp,9,ap,43),0);assert_eq!(m[0],0xa5);assert!(m[95..].iter().all(|b|*b==0xa5));assert_eq!((f[0],f[10],a[0],a[44]),(0xa5,0xa5,0xa5,0xa5));}}
#[test] fn bip84_public_zero_fixture(){let(r,m,f,a)=run(b"00000000000000000000000000000000");assert_eq!(r,0);assert_eq!(text(&m),"abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about");assert_eq!(text(&f),"73c5da0a");assert_eq!(text(&a),"bc1qcr8te4kr609gcawutmrza0j4xv80jy8z306fyu");}
